("pandaren", "The pandaren", "PF", "The people of Pandaria, hidden behind mists since the Sundering, whose culture is built on mastering the emotions that feed the Sha.", ["V", "XI"]),
("primalists", "The Primalists &amp; Incarnates", "PF", "Proto-dragons and elemental zealots who refused the titans' gift, led by the four Primal Incarnates. Defeated in the War of the Scaleborn; their modern cult frees Raszageth on the eve of Dragonflight.", ["III", "XIV"]),
("scourge", "The Scourge", "PF", "The Lich King's undead army, raised by plague to soften Azeroth for the Legion — and dangerous enough to slip that leash.", ["VII", "VIII", "X"]),
("tauren", "The tauren", "PF", "Nomadic bison-folk of Kalimdor's plains, ancient followers of the Earth Mother; among Thrall's first and truest allies in the new Horde.", ["V", "VIII"]),
("titanforged", "The titan-forged &amp; keepers", "PF", "Armies of stone and metal forged by the titans to fight the Black Empire, led by empowered keepers such as Tyr and Odyn. Their cursed descendants became many of the mortal races.", ["I", "II", "III"]),
("titans", "The titans &amp; the Pantheon", "PF", "God-like beings of Order born from world-souls, governed by the Pantheon under Aman'Thul. Shattered by Sargeras's betrayal; their spirits restored at Argus to imprison him.", ["I", "II", "XII"]),
("trolls", "The trolls", "PF", "The Eastern Kingdoms' oldest empires and Kalimdor's ancient tribes; the night elves' own distant ancestors. Their wars against the high elves forged the human-elf alliance.", ["V", "XIII"]),
("void-lords", "The Void Lords", "PF", "Entities of hungering shadow outside reality, whose plan is to corrupt a world-soul into a Dark Titan of the Void. The Old Gods are their weapons.", ["I", "II", "XIII"]),
("wild-gods", "The Wild Gods", "PF", "Great beast-spirits of Life empowered by the keepers — Cenarius's kin among them — tied to the Emerald Dream.", ["II", "IV"]),

# ---------- Places & Realms ----------
("argus", "Argus", "PL", "Homeworld of the eredar, seized by the Legion as its throneworld — and revealed to hold a tortured world-soul used as the Legion's resurrection engine. Site of Sargeras's imprisonment.", ["VI", "XII"]),
