("dragon-isles", "The Dragon Isles", "PL", "The dragons' ancient homeland and seat of the Aspects' power, dormant since the flights withdrew — reawakened on the eve of Dragonflight.", ["III", "XIV"]),
("eastern-kingdoms", "The Eastern Kingdoms", "PL", "The eastern continents born of the Sundering: home of the human Seven Kingdoms, Quel'Thalas, Ironforge, and the ruins of Lordaeron.", ["IV", "V"]),
("emerald-dream", "The Emerald Dream", "PL", "The verdant blueprint-realm of Life, tended by the green dragonflight and the druids. Corrupted into the Nightmare during the Legion invasion.", ["I", "III", "XII"]),
("icecrown", "Icecrown Citadel", "PL", "The Lich King's fortress in Northrend, seat of the Frozen Throne — where Arthas fell and where Sylvanas later shattered the Helm of Domination.", ["X", "XIII"]),
("kalimdor", "Kalimdor", "PL", "The western continent born of the Sundering: land of the night elves, tauren, and the Horde's new home of Durotar.", ["IV", "VIII"]),
("lordaeron", "Lordaeron", "PL", "The proudest of the human Seven Kingdoms, destroyed by its own prince in the Third War; its plagued ruins became the Forsaken's Undercity.", ["V", "VII", "VIII", "XIII"]),
("nordrassil", "Nordrassil", "PL", "The World Tree planted over the Well of Eternity's remnant at Mount Hyjal, blessed by three Aspects. Its sacrifice destroyed Archimonde — and cost the night elves their immortality.", ["IV", "VIII"]),
("northrend", "Northrend", "PL", "The frozen crown of the world: the Lich King's domain, Ulduar's resting place, and the battleground of the war against the Scourge.", ["IV", "VII", "X"]),
("orgrimmar", "Orgrimmar", "PL", "The Horde's capital in Durotar, founded by Thrall — and besieged by its own people to depose Garrosh.", ["IX", "XI"]),
("outland", "Draenor / Outland", "PL", "The orcs' and draenei's savage homeworld, shattered by Ner'zhul's portals into the floating ruin called Outland — later ruled by Illidan. An intact alternate-timeline Draenor hosts the Warlords campaign.", ["VI", "VII", "IX", "XII"]),
("pandaria", "Pandaria", "PL", "The mist-hidden southern continent, homeland of the pandaren and resting place of Y'Shaarj's lingering Sha — dragged into the faction war upon its discovery.", ["II", "V", "XI"]),
("quelthalas", "Quel'Thalas", "PL", "The high elves' forest kingdom in the north of the Eastern Kingdoms, built around the Sunwell; carved apart by Arthas in the Third War.", ["V", "VIII"]),
("shadowlands", "The Shadowlands", "PL", "The realm of Death: an afterlife machinery of soul-triage whose realms starved while the Jailer diverted every soul into the torture-pit of the Maw.", ["I", "XIII"]),
("silithus", "Silithus", "PL", "The desert prison-ground of C'Thun — and the place where Sargeras's sword now stands impaled in the world, bleeding Azerite.", ["IX", "XII", "XIII"]),
("stormwind", "Stormwind", "PL", "The southernmost human kingdom: first casualty of the Horde's invasion, rebuilt to become the Alliance's modern capital under the Wrynn kings.", ["V", "VII", "IX"]),
("sunwell", "The Sunwell", "PL", "The fount of power at Quel'Thalas's heart, kindled from the old Well's waters. Defiled by Arthas; reborn through the naaru M'uru's heart as a well of Light and arcane both.", ["V", "VIII", "IX"]),
("teldrassil", "Teldrassil", "PL", "The second World Tree, grown as the night elves' island home — burned with its civilians by Sylvanas's order at the start of the Fourth War.", ["XIII"]),
("ulduar", "Ulduar", "PL", "The titan machine-city in Northrend built to watch Yogg-Saron's prison — whose jailers the Old God corrupted from within.", ["II", "X"]),
("vault-incarnates", "The Vault of the Incarnates", "PL", "The prison built for the defeated Incarnates: sealed by Nozdormu's temporal locks, Malygos's arcane wards, and Neltharion's burial. Raszageth was held separately in the Froststone Vault of the Forbidden Reach.", ["III", "XIV"]),
("well-of-eternity", "The Well of Eternity", "PL", "The becalmed lake of the world-soul's own lifeblood, formed from the wound of Y'Shaarj's removal. Fountainhead of night elf civilization; destroyed in the Sundering — its stolen waters kindled new wells.", ["II", "IV", "V"]),

# ---------- Artifacts & Substances ----------
("azerite", "Azerite", "AR", "The crystallized lifeblood of Azeroth's world-soul, welling from the sword-wound in Silithus — a weaponizable god-blood whose promise ignited the Fourth War.", ["XII", "XIII"]),
("demon-soul", "The Dragon Soul / Demon Soul", "AR", "The golden disc Neltharion forged in secret, holding a portion of every flight's essence except his own. His weapon of betrayal — and, ten thousand years later, the only weapon that could unmake him.", ["IV", "XI"]),
("frostmourne", "Frostmourne", "AR", "The soul-drinking runeblade of the Frozen Throne, taken by Arthas at the cost of his soul. Shattered at Icecrown's summit, releasing the souls it had devoured.", ["VII", "VIII", "X"]),
("heart-yshaarj", "The Heart of Y'Shaarj", "AR", "The sealed heart of the slain Old God, unearthed and awakened by Garrosh Hellscream in Pandaria's sacred vale.", ["II", "XI"]),
("helm", "The Helm of Domination", "AR", "The crown that housed the Lich King's will, worn in turn by Ner'zhul's spirit, Arthas, and Bolvar — until Sylvanas shattered it and tore open the sky.", ["VII", "VIII", "X", "XIII"]),
("sword-sargeras", "The Sword of Sargeras", "AR", "The continent-sized blade Sargeras drove into Silithus as he was imprisoned — a lasting wound in the world-soul, still standing in the desert.", ["XII", "XIII"]),

# ---------- Events & Terms ----------
("aspect", "Aspect", "EV", "One of five dragons empowered by the Pantheon (through the keepers, at Tyr's urging) as guardians of a domain of the world: life, dreams, time, magic, and earth. Their powers were spent destroying Deathwing.", ["III", "XI", "XIV"]),
("curse-of-flesh", "The curse of flesh", "EV", "The Old Gods' disease that softened the titan-forged from stone and metal into mortal flesh — the origin of humans, dwarves, gnomes, and others.", ["II", "V"]),
